 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Fill the intervals between consecutive 5s along each row and column.
    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value == 5]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                if out[r][c] != 5:
                    out[r][c] = 3

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == 5]
        for top, bottom in zip(marks, marks[1:]):
            for r in range(top + 1, bottom):
                if out[r][c] != 5:
                    out[r][c] = 3

    return out
